import{_ as l,a0 as i,w as d,s as m,I as o,x as t,a1 as n,A as a,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Alien 魔法：RPM 和 DEB 互轉 | LCTT x X-CMD","titleTemplate":false,"description":"Alien 魔法：RPM 和 DEB 互轉 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Alien 魔法：RPM 和 DEB 互轉 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Alien 魔法：RPM 和 DEB 互轉 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150827 How to Convert From RPM to DEB and DEB to RPM Package Using Alien","title":"Alien 魔法：RPM 和 DEB 互轉","tag":"201508","desc":""},"relativePath":"201508/20150827 How to Convert From RPM to DEB and DEB to RPM Package Using Alien.md","filePath":"[post].md"}'),s={name:"201508/20150827 How to Convert From RPM to DEB and DEB to RPM Package Using Alien.md"};function u(c,e,g,w,P,b){const p=i("Link");return d(),m("div",null,[e[19]||(e[19]=o("h1",{id:"alien-魔法-rpm-和-deb-互轉",tabindex:"-1"},[t("Alien 魔法：RPM 和 DEB 互轉 "),o("a",{class:"header-anchor",href:"#alien-魔法-rpm-和-deb-互轉","aria-label":"Permalink to “Alien 魔法：RPM 和 DEB 互轉”"},"​")],-1)),o("p",null,[e[1]||(e[1]=t("正如我確信，你們一定知道Linux下的多種軟件安裝方式：使用發行版所提供的包管理系統（",-1)),n(p,{href:"http://www.tecmint.com/linux-package-management/"},{default:a(()=>[...e[0]||(e[0]=[t("aptitude，yum，或者zypper",-1)])]),_:1}),e[2]||(e[2]=t("，還可以舉很多例子），從源碼編譯（儘管現在很少用了，但在Linux發展早期卻是唯一可用的方法），或者使用各自的低級工具dpkg用於.deb，以及rpm用於.rpm，預編譯包，如此這般。",-1))]),e[20]||(e[20]=r(`<p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Convert-RPM-to-DEB-and-DEB-to-RPM.png" alt="Convert RPM to DEB and DEB to RPM"></p><p><em>使用Alien將RPM轉換成DEB以及將DEB轉換成RPM</em></p><p>在本文中，我們將為你介紹alien，一個用於在各種不同的Linux包格式相互轉換的工具，其最常見的用法是將.rpm轉換成.deb（或者反過來）。</p><p>如果你需要某個特定類型的包，而你只能找到其它格式的包的時候，該工具遲早能派得上用場——即使是其作者不再維護，並且在其網站聲明：alien將可能永遠維持在實驗狀態。</p><p>例如，有一次，我正查找一個用於噴墨打印機的.deb驅動，但是卻沒有找到——生產廠家只提供.rpm包，這時候alien拯救了我。我安裝了alien，將包進行轉換，不久之後我就可以使用我的打印機了，沒有任何問題。</p><p>即便如此，我們也必須澄清一下，這個工具不應當用來轉換重要的系統文件和庫，因為它們在不同的發行版中有不同的配置。只有在前面説的那種情況下所建議的安裝方法根本不適合時，alien才能作為最後手段使用。</p><p>最後一項要點是，我們必須注意，雖然我們在本文中使用CentOS和Debian，除了前兩個發行版及其各自的家族體系外，據我們所知，alien可以工作在Slackware中，甚至Solaris中。</p><h3 id="步驟1-安裝alien及其依賴包" tabindex="-1">步驟1：安裝Alien及其依賴包 <a class="header-anchor" href="#步驟1-安裝alien及其依賴包" aria-label="Permalink to “步驟1：安裝Alien及其依賴包”">​</a></h3><p>要安裝alien到CentOS/RHEL 7中，你需要啓用EPEL和Nux Dextop（是的，是Dextop——不是Desktop）倉庫，順序如下：</p><pre><code># yum install epel-release
</code></pre>`,10)),o("p",null,[e[4]||(e[4]=t("啓用Nux Dextop倉庫的包的當前最新版本是0.5（2015年8月10日發佈），在安裝之前你可以查看",-1)),n(p,{href:"http://li.nux.ro/download/nux/dextop/el7/x86_64/"},{default:a(()=>[...e[3]||(e[3]=[t("http://li.nux.ro/download/nux/dextop/el7/x86_64/",-1)])]),_:1}),e[5]||(e[5]=t("上是否有更新的版本。",-1))]),e[21]||(e[21]=r(`<pre><code># rpm --import http://li.nux.ro/download/nux/RPM-GPG-KEY-nux.ro
# rpm -Uvh http://li.nux.ro/download/nux/dextop/el7/x86_64/nux-dextop-release-0-5.el7.nux.noarch.rpm
</code></pre><p>然後再做，</p><pre><code># yum update &amp;&amp; yum install alien
</code></pre><p>在Fedora中，你只需要運行上面的命令即可。</p><p>在Debian及其衍生版中，只需要：</p><pre><code># aptitude install alien
</code></pre><h3 id="步驟2-將-deb轉換成-rpm包" tabindex="-1">步驟2：將.deb轉換成.rpm包 <a class="header-anchor" href="#步驟2-將-deb轉換成-rpm包" aria-label="Permalink to “步驟2：將.deb轉換成.rpm包”">​</a></h3><p>對於本次測試，我們選擇了date工具，它提供了一系列日期和時間工具用於處理大量金融數據。我們將下載.deb包到我們的CentOS 7機器中，將它轉換成.rpm並安裝：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Check-Linux-OS-Version.png" alt="Check CentOS Version"></p><p>檢查CentOS版本</p><pre><code># cat /etc/centos-release
# wget http://ftp.us.debian.org/debian/pool/main/d/dateutils/dateutils_0.3.1-1.1_amd64.deb
# alien --to-rpm --scripts dateutils_0.3.1-1.1_amd64.deb
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Convert-deb-to-rpm-package.png" alt="Convert .deb to .rpm package in Linux"></p><p><em>在Linux中將.deb轉換成.rpm</em></p><p><strong>重要</strong>：（請注意alien是怎樣來增加目標包的次版本號的。如果你想要無視該行為，請添加-keep-version標識）。</p><p>如果我們嘗試馬上安裝該包，我們將碰到些許問題：</p><pre><code># rpm -Uvh dateutils-0.3.1-2.1.x86_64.rpm 
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-RPM-Package.png" alt="Install RPM Package"></p><p><em>安裝RPM包</em></p><p>要解決該問題，我們需要啓用epel-testing倉庫，然後安裝rpmbuild工具來編輯該包的配置以重建包：</p><pre><code># yum --enablerepo=epel-testing install rpmrebuild
</code></pre><p>然後運行，</p><pre><code># rpmrebuild -pe dateutils-0.3.1-2.1.x86_64.rpm
</code></pre><p>它會打開你的默認文本編輯器。請轉到<code>%files</code>章節並刪除涉及到錯誤信息中提到的目錄的行，然後保存文件並退出：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Convert-Deb-Package-to-Alien-Version.png" alt="Convert .deb to Alien Version"></p><p><em>轉換.deb到Alien版</em></p><p>但你退出該文件後，將提示你繼續去重構。如果你選擇“Y”，該文件會重構到指定的目錄（與當前工作目錄不同）：</p><pre><code># rpmrebuild –pe dateutils-0.3.1-2.1.x86_64.rpm
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Build-RPM-Package.png" alt="Build RPM Package"></p><p><em>構建RPM包</em></p><p>現在你可以像以往一樣繼續來安裝包並驗證：</p><pre><code># rpm -Uvh /root/rpmbuild/RPMS/x86_64/dateutils-0.3.1-2.1.x86_64.rpm
# rpm -qa | grep dateutils
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-Build-RPM-Package.png" alt="Install Build RPM Package"></p><p><em>安裝構建RPM包</em></p><p>最後，你可以列出date工具包含的各個工具，也可以查看各自的手冊頁：</p><pre><code># ls -l /usr/bin | grep dateutils
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Verify-Installed-Package.png" alt="Verify Installed RPM Package"></p><p><em>驗證安裝的RPM包</em></p><h3 id="步驟3-將-rpm轉換成-deb包" tabindex="-1">步驟3：將.rpm轉換成.deb包 <a class="header-anchor" href="#步驟3-將-rpm轉換成-deb包" aria-label="Permalink to “步驟3：將.rpm轉換成.deb包”">​</a></h3><p>在本節中，我們將演示如何將.rpm轉換成.deb。在一台32位的Debian Wheezy機器中，讓我們從CentOS 6操作系統倉庫中下載用於zsh shell的.rpm包。注意，該shell在Debian及其衍生版的默認安裝中是不可用的。</p><pre><code># cat /etc/shells
# lsb_release -a | tail -n 4
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Check-Shell-Debian-OS-Version.png" alt="Check Shell and Debian OS Version"></p><p><em>檢查Shell和Debian操作系統版本</em></p><pre><code># wget http://mirror.centos.org/centos/6/os/i386/Packages/zsh-4.3.11-4.el6.centos.i686.rpm
# alien --to-deb --scripts zsh-4.3.11-4.el6.centos.i686.rpm
</code></pre><p>你可以安全地無視關於簽名丟失的信息：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Convert-rpm-to-deb-Package.png" alt="Convert .rpm to .deb Package"></p><p><em>將.rpm轉換成.deb包</em></p><p>過了一會兒後，.deb包應該已經生成，並可以安裝了：</p><pre><code># dpkg -i zsh_4.3.11-5_i386.deb
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-Deb-Package.png" alt="Install RPM Converted Deb Package"></p><p><em>安裝RPM轉換來的Deb包</em></p><p>安裝完後，你看看可以zsh是否添加到了合法shell列表中：</p><pre><code># cat /etc/shells
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Confirm-Installed-Package.png" alt="Confirm Installed Zsh Package"></p><p><em>確認安裝的Zsh包</em></p><h3 id="小結" tabindex="-1">小結 <a class="header-anchor" href="#小結" aria-label="Permalink to “小結”">​</a></h3><p>在本文中，我們已經解釋瞭如何將.rpm轉換成.deb及其反向轉換，這可以作為這類程序不能從倉庫中或者作為可分發源代碼獲得的最後安裝手段。你一定想要將本文添加到書籤中，因為我們都需要alien。</p><p>請自由分享你關於本文的想法，寫到下面的表單中吧。</p><hr>`,58)),o("p",null,[e[7]||(e[7]=t("via: ",-1)),n(p,{href:"http://www.tecmint.com/convert-from-rpm-to-deb-and-deb-to-rpm-package-using-alien/"},{default:a(()=>[...e[6]||(e[6]=[t("http://www.tecmint.com/convert-from-rpm-to-deb-and-deb-to-rpm-package-using-alien/",-1)])]),_:1})]),o("p",null,[e[11]||(e[11]=t("作者：",-1)),n(p,{href:"http://www.tecmint.com/author/gacanepa/"},{default:a(()=>[...e[8]||(e[8]=[t("Gabriel Cánepa",-1)])]),_:1}),e[12]||(e[12]=t(" 譯者：",-1)),n(p,{href:"https://github.com/GOLinux"},{default:a(()=>[...e[9]||(e[9]=[t("GOLinux",-1)])]),_:1}),e[13]||(e[13]=t(" 校對：",-1)),n(p,{href:"https://github.com/wxy"},{default:a(()=>[...e[10]||(e[10]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[16]||(e[16]=t("本文由 ",-1)),n(p,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[14]||(e[14]=[t("LCTT",-1)])]),_:1}),e[17]||(e[17]=t(" 原創翻譯，",-1)),n(p,{href:"https://linux.cn/"},{default:a(()=>[...e[15]||(e[15]=[t("Linux中國",-1)])]),_:1}),e[18]||(e[18]=t(" 榮譽推出",-1))])])}const k=l(s,[["render",u]]);export{C as __pageData,k as default};
